pub fn config(endpoint: Endpoint) -> Result<core::result::Result<Config, Error>> {
    let mut buffer = Pages::new(4096).ok_or(SysError::NoMemory)?;
    let length = {
        let mut w = Writer::new(buffer.as_mut_slice());
        w.len()
    };
    let reply = wire::call_buffer(endpoint, 1 | MAJOR << 8, &buffer, length)?;
    if let Some(code) = wire::enum_error(&reply)? { return Ok(Err(Error::from_code(code).ok_or(SysError::Invalid)?)); }
    let length = wire::buffer_reply(&reply, 22, false, false)?;
    let length = length.ok_or(SysError::Invalid)?;
    Ok(Ok({ let mut r = Reader::new(&buffer.as_slice()[..length]); <Config as Wire>::decode(&mut r).filter(|_| r.done()).ok_or(SysError::Invalid)? }))
}

/// ICMP echo to `address`; returns the round trip in microseconds.
pub fn ping(endpoint: Endpoint, address: u32, timeout_ms: u32) -> Result<core::result::Result<u32, Error>> {
    let words = [2 | MAJOR << 8 | ((address) as usize) << 16, ((timeout_ms) as usize) << 0];
    let reply = wire::call(endpoint, words, None)?;
    if let Some(code) = wire::enum_error(&reply)? { return Ok(Err(Error::from_code(code).ok_or(SysError::Invalid)?)); }
    let _ = wire::check_reply(&reply, [0xffffffff0000, 0x0], false)?;
    Ok(Ok(wire::field(&reply, 0, 16, 32) as u32))
}

